// @flow
const argparse = require("argparse");
const drupal = require("./drupal.js");
const mysql = require("./mysql.js");
import type { Obj } from "./utils.js";

const parser = new argparse.ArgumentParser({
  addHelp: true,
  description: "Migrate Satire V from Drupal to Directus"
});
parser
  .addArgument(["-d", "--database"], {
    help: "The name of the drupal database",
    defaultValue: "satirevdrupal",
    type: "string",
    dest: "database"
  })
  .addArgument(["-p", "--password"], {
    help: "The password to the drupal database",
    type: "string",
    dest: "password"
  });

async function processAllInlineFiles(postData: Obj, db: Obj) {
  const res1 = await drupal.genProcessManagedToPublicFiles(postData.body, db);
  const res2 = await drupal.genProcessHTMLImageTags(
    res1,
    postData.relative_uri
  );
  postData.body = res2;
  console.log(postData.body);
  return postData;
}

async function main() {
  const args = parser.parseArgs();
  const db = await mysql.newDB(args.db, args.password);
  const testArticles = drupal.fetchFullDatabase(db);
  await processAllInlineFiles(testArticles[0], db);
}

main();
